// Available UI component types for offers
type ComponentType string

const (
	ComponentTypeShortDescription ComponentType = "shortDescription"
	ComponentTypeLongDescription  ComponentType = "longDescription"
	ComponentTypeBaseReward       ComponentType = "baseReward"
	ComponentTypeBoostedReward    ComponentType = "boostedReward"
	ComponentTypeCta              ComponentType = "cta"
	ComponentTypeTags             ComponentType = "tags"
	ComponentTypeDetailTags       ComponentType = "detailTags"
	ComponentTypeLogoFlare        ComponentType = "logoFlare"
	ComponentTypeProgressBar      ComponentType = "progressBar"
)

func NewComponentTypeFromString(s string) (ComponentType, error) {
	switch s {
	case "shortDescription":
		return ComponentTypeShortDescription, nil
	case "longDescription":
		return ComponentTypeLongDescription, nil
	case "baseReward":
		return ComponentTypeBaseReward, nil
	case "boostedReward":
		return ComponentTypeBoostedReward, nil
	case "cta":
		return ComponentTypeCta, nil
	case "tags":
		return ComponentTypeTags, nil
	case "detailTags":
		return ComponentTypeDetailTags, nil
	case "logoFlare":
		return ComponentTypeLogoFlare, nil
	case "progressBar":
		return ComponentTypeProgressBar, nil
	}
	var t ComponentType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (c ComponentType) Ptr() *ComponentType {
	return &c
}

